const body = $input.first().json;
const request = $('Research input').first().json;
if (typeof body.code !== 'number' || body.code !== 0) throw new Error('API business error; inspect HTTP output before any repeat request.');
const d = body.data;
if (!d || !['AVAILABLE','PARTIAL'].includes(d.resourceStatus)) throw new Error('Resource unavailable or unknown; no rows exported.');
const cell = v => {
  if(v == null) return '';
  if(typeof v === 'object') v=JSON.stringify(v);
  return typeof v === 'string' && (/^[\t\r\n]/.test(v) || /^[=+\-@]/.test(v.trimStart())) ? "'"+v : v;
};
const sourceUrl = v => { if(typeof v!=='string' || !/^https:\/\/[A-Za-z0-9.-]+(?::[0-9]+)?(?:[/?#][^\s]*)?$/.test(v)) throw new Error('Missing or invalid HTTPS source URL.'); return v; };
const common = {
  resource_status:d.resourceStatus, fetched_at:d.fetchedAt ?? '', source_fetched_at:d.sourceFetchedAt ?? '',
  observed_at_utc:new Date().toISOString(),execution_id:String($execution.id),
  query_or_input:request.keyword ?? request.url ?? request.handle ?? request.query,
  has_more: d.hasMore ?? '', next_cursor:d.nextCursor ?? ''
};
const finish = (rows, returned) => rows.map(row=>{
  const missing=Object.keys(row).filter(k=>row[k]==null);
  const output={...row,...common,returned_count:returned,exported_count:rows.length,missing_fields:missing.join(';')};
  return {json:Object.fromEntries(Object.entries(output).map(([k,v])=>[k,cell(v)]))};
});
if(!Array.isArray(d.items))throw new Error('Expected data.items array.');
const gate=$('Validate profile').first().json;
const expected=request.handle.replace(/^@/,'').toLowerCase();
const rows=[];const seen=new Set();
for(const p of d.items.slice(0,20)) {
 if(!p || typeof p.id!=='string' || !p.id)throw new Error('Missing post ID.');
 if(p.author?.handle && p.author.handle.replace(/^@/,'').toLowerCase()!==expected)throw new Error('Post author handle mismatch.');
 const url=sourceUrl(p.url);if(seen.has(p.id))continue;seen.add(p.id);
 rows.push({source_id:p.id,source_url:url,handle:request.handle,profile_url:gate.profile_url,follower_count:gate.follower_count,caption:p.caption,media_type:p.type,published_at:p.publishedAt,like_count:p.likeCount,comment_count:p.commentCount,view_count:p.viewCount,profile_resource_status:gate.profile_resource_status,profile_fetched_at:gate.profile_fetched_at});
}
return finish(rows,d.items.length);
